import{_ as e,o,c as n,ah as s}from"./chunks/framework.D4KxWb5R.js";const m=JSON.parse('{"title":"Communications and resources","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/administration/communications.md","filePath":"src/en/guide/administration/communications.md"}'),i={name:"en/guide/administration/communications.md"};function r(a,t,c,d,l,h){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="communications-and-resources" tabindex="-1">Communications and resources <a class="header-anchor" href="#communications-and-resources" aria-label="Permalink to &quot;Communications and resources&quot;">​</a></h1><p>Open to the CEO and to Partner &amp; Customer Support.</p><h2 id="communications" tabindex="-1">Communications <a class="header-anchor" href="#communications" aria-label="Permalink to &quot;Communications&quot;">​</a></h2><p>A communication is an announcement published in the intranet, visible as soon as it is saved.</p><ol><li><p><strong>Administration → Communications → New communication</strong>.</p></li><li><p>Enter the <strong>title</strong> and <strong>message</strong>, and choose the language it is <strong>written in</strong> (English or French).</p></li><li><p>Choose the <strong>recipients</strong>:</p><table tabindex="0"><thead><tr><th>Recipients</th><th>Who receives it</th></tr></thead><tbody><tr><td>All of M&#39;City</td><td>Every account</td></tr><tr><td>Product</td><td>Accounts whose scope covers the product</td></tr><tr><td>Zone</td><td>Accounts assigned the zone, or with an office in the zone</td></tr><tr><td>Office</td><td>Accounts assigned the office (HR and Finance cover all offices)</td></tr><tr><td>Department</td><td>Accounts attached to the department</td></tr><tr><td>Position</td><td>Accounts with that position</td></tr><tr><td>Chosen recipients</td><td>The selected accounts</td></tr></tbody></table></li><li><p>Choose one or more <strong>targets</strong>: an account receives the communication if its assignment matches at least one of them. Management (CEO and heads) covers all products, zones and offices.</p></li><li><p><strong>Publish</strong>.</p></li></ol><p>Recipients are told through a <a href="./../notifications.html">notification</a>. Those who publish can edit or delete a communication; deleting it removes it from every recipient&#39;s intranet.</p><h2 id="shared-resources" tabindex="-1">Shared resources <a class="header-anchor" href="#shared-resources" aria-label="Permalink to &quot;Shared resources&quot;">​</a></h2><p><strong>Administration → Resources</strong> manages the intranet&#39;s documents, procedures, notes, contacts and links.</p><ol><li><strong>New resource</strong>.</li><li>Choose the <strong>type</strong> and enter the <strong>title</strong> and <strong>text</strong>, in English and French.</li><li>Depending on the type: <ul><li>document: attach the <strong>file</strong> (PDF, office document, text or image, 2 MB at most);</li><li>link: enter the <strong>link address</strong>.</li></ul></li><li><strong>Product</strong>: leave <strong>General (all of M&#39;City)</strong> for a resource everyone sees, or choose an active product to keep it for the accounts whose scope covers it. It then also appears in the product&#39;s space.</li><li><strong>Create the resource</strong>.</li></ol><p>The accounts concerned are notified. Deleting a resource also deletes its file, for good. A file can be downloaded only after the reader&#39;s scope is checked.</p>',10)])])}const p=e(i,[["render",r]]);export{m as __pageData,p as default};
